/* Checkmark drawn on completion. */
.tick { width: 1em; height: 1em; flex: none; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.tick path { stroke-dasharray: 1; animation: tick-draw 220ms var(--ease-out) both; }
@keyframes tick-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }

/* Progress bars grow with transform from the left edge (--p is 0..1). */
.bar > i { width: 100%; transform: scaleX(clamp(0, var(--p, 1), 1)); transform-origin: left; transition: transform var(--dur-4) var(--ease-out); }

/* Expandable blocks: the height animates through grid rows. */
.reveal { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--dur-2) var(--ease-out); }
.reveal.open { grid-template-rows: 1fr; }
.reveal > * { min-height: 0; overflow: hidden; }

/* Segmented control with a sliding plate (--n options, --i active). */
.seg.sliding { position: relative; display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); }
